// Simple versioned event parser
function parseEvent(event) {
  const v = event.version || 1;
  if (v === 1) {
    return { userId: event.uid, action: event.act };
  } else if (v === 2) {
    return { userId: event.user_id, action: event.action, meta: event.meta };
  }
  return null;
}
```

